async function handleListConversations(
  ws: WebSocket,
  message: ListConversationsMessage,
  options?: MessageHandlerOptions
): Promise<void> {
  if (!options?.history?.enabled || !options.sessionStore?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
    return;
  }
  const userId = (ws as ExtWebSocket).userId;
  try {
    const summaries = await options.sessionStore.listFor(userId, {
      limit: message.limit,
      before: message.before,
    });
    sendConversationList(ws, summaries.map(toConversationSummary));
  } catch (error) {
    const msg = error instanceof Error ? error.message : String(error);
    log.error('message', 'list_conversations failed', {error: msg});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

function toConversationSummary(summary: SessionSummary): ConversationSummary {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt instanceof Date ? summary.createdAt.toISOString() : new Date(summary.createdAt).toISOString(),
    updatedAt: summary.updatedAt instanceof Date ? summary.updatedAt.toISOString() : new Date(summary.updatedAt).toISOString(),
    entryCount: summary.entryCount,
  };
}

